// Keeps the screen from sleeping while a game is on screen — mobile browsers
// dim/lock the screen on their own timer regardless of an active game, and a
// locked screen is also what triggers most of the WebSocket drops
// networkMode.ts's reconnect logic works around.
//
// The native Screen Wake Lock API alone isn't enough: it's unsupported in
// many iOS in-app webviews (KakaoTalk's included) even on iOS versions
// where Safari itself has it, and it wasn't in Safari at all before 16.4 —
// this was reported not actually keeping the screen on in Safari. So
// whenever `navigator.wakeLock` doesn't exist, this falls back to the
// classic muted-looping-video trick (the same one the widely-used
// NoSleep.js library uses: https://github.com/richtr/NoSleep.js) — mobile
// browsers have treated active video playback as a "don't sleep" signal
// for far longer than the Wake Lock API has existed, so it covers browsers
// the native API can't. Either path is a silent no-op if it doesn't work
// (rejected permission, autoplay blocked, etc.) — never a crash.
//
// The browser itself releases a held native lock (and can pause the video)
// the moment the tab is hidden, so `wanted` tracks intent separately from
// whether a lock/video is currently active, and a visibilitychange
// listener re-acquires it on return to the foreground if still wanted.

// The exact video data URI NoSleep.js embeds (src/media.js in that repo) —
// a ~1s black, silent, minimal MP4. Copied byte-for-byte via a real MP4
// decode/verify pass, not retyped, since a single wrong character would
// silently corrupt it.
const NOSLEEP_VIDEO_SRC = "data:video/mp4;base64,";

let sentinel: WakeLockSentinel | null = null;
let videoEl: HTMLVideoElement | null = null;
let wanted = false;
let listenerAttached = false;

function hasNativeWakeLock(): boolean {
  return typeof navigator !== "undefined" && "wakeLock" in navigator;
}

function ensureVideoElement(): HTMLVideoElement | null {
  if (videoEl || typeof document === "undefined") return videoEl;
  const video = document.createElement("video");
  video.setAttribute("title", "");
  video.setAttribute("playsinline", "");
  video.muted = true;
  video.setAttribute("muted", "");
  const source = document.createElement("source");
  source.src = NOSLEEP_VIDEO_SRC;
  source.type = "video/mp4";
  video.appendChild(source);
  // Off-screen but not display:none/visibility:hidden — some browsers
  // pause or heavily throttle playback of video that isn't actually
  // rendered anywhere.
  video.style.position = "fixed";
  video.style.width = "1px";
  video.style.height = "1px";
  video.style.opacity = "0";
  video.style.pointerEvents = "none";
  // The clip is under a second — some engines don't honor the native
  // `loop` attribute reliably at that length, so loop it manually instead
  // (same approach NoSleep.js uses for its mp4 fallback source).
  video.addEventListener("timeupdate", () => {
    if (video.currentTime > 0.5) video.currentTime = Math.random();
  });
  document.body.appendChild(video);
  videoEl = video;
  return video;
}

async function tryAcquire(): Promise<void> {
  if (!wanted) return;
  if (hasNativeWakeLock()) {
    if (sentinel) return;
    try {
      sentinel = await navigator.wakeLock.request("screen");
      sentinel.addEventListener("release", () => {
        sentinel = null;
      });
    } catch {
      sentinel = null;
    }
    return;
  }
  ensureVideoElement()
    ?.play()
    .catch(() => {});
}

// Attached lazily (not at module load) so importing this module — e.g.
// transitively, via render.ts, from a test that never touches a real DOM —
// doesn't itself require `document` to exist.
function ensureVisibilityListener(): void {
  if (listenerAttached || typeof document === "undefined") return;
  listenerAttached = true;
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") tryAcquire();
  });
}

export function enableScreenWakeLock(): void {
  ensureVisibilityListener();
  if (wanted) return;
  wanted = true;
  tryAcquire();
}

export function disableScreenWakeLock(): void {
  wanted = false;
  const held = sentinel;
  sentinel = null;
  held?.release().catch(() => {});
  videoEl?.pause();
}
